import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.DDY-poMm.js";const g=JSON.parse('{"title":"Source Code Delivery and Compliance Disclaimer for the Digital Asset Trading System","description":"","frontmatter":{},"headers":[],"relativePath":"legal/disclaimer.md","filePath":"legal/disclaimer.md","lastUpdated":1790683574000}'),n={name:"legal/disclaimer.md"};function o(s,e,l,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="source-code-delivery-and-compliance-disclaimer-for-the-digital-asset-trading-system" tabindex="-1">Source Code Delivery and Compliance Disclaimer for the Digital Asset Trading System <a class="header-anchor" href="#source-code-delivery-and-compliance-disclaimer-for-the-digital-asset-trading-system" aria-label="Permalink to &quot;Source Code Delivery and Compliance Disclaimer for the Digital Asset Trading System&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Language</p><p>This English text is a translation for convenience. In case of any discrepancy, the <a href="/CoinExchange/zh/legal/disclaimer">Chinese version</a> prevails.</p></div><div class="warning custom-block"><p class="custom-block-title">Important notice</p><p>The source code of this system (the &quot;Software&quot;) is delivered and licensed solely as a computer software technology product. Before obtaining, deploying, customizing or operating the Software, the purchaser must carefully read and comply with all terms of this Disclaimer. Receiving, downloading, deploying or using the Software constitutes full understanding and acceptance of all terms of this Disclaimer.</p><p><strong>This system is intended solely for lawful, compliant operation outside mainland China. Operating it within mainland China is strictly prohibited.</strong></p></div><h2 id="_1-technical-delivery-and-neutrality" tabindex="-1">1. Technical delivery and neutrality <a class="header-anchor" href="#_1-technical-delivery-and-neutrality" aria-label="Permalink to &quot;1. Technical delivery and neutrality&quot;">​</a></h2><p><strong>Purely technical delivery</strong>: The delivering party provides the purchaser only with the underlying computer software source code or compiled programs. The delivery is purely a technology development / transfer / licensing arrangement.</p><p><strong>Not a financial or operating entity</strong>: The delivering party does not take part in any of the purchaser&#39;s subsequent commercial operations, node maintenance, liquidity provision, market making or matching, funds clearing, asset custody or investment advisory services.</p><p><strong>Technology neutrality</strong>: The delivering party has no substantive control or decision-making power over how the purchaser uses the Software, and bears no joint liability for the operation of any platform built on the Software.</p><h2 id="_2-purchaser-s-legal-qualifications-and-compliance-undertakings" tabindex="-1">2. Purchaser&#39;s legal qualifications and compliance undertakings <a class="header-anchor" href="#_2-purchaser-s-legal-qualifications-and-compliance-undertakings" aria-label="Permalink to &quot;2. Purchaser&#39;s legal qualifications and compliance undertakings&quot;">​</a></h2><p>The purchaser irrevocably undertakes and warrants that:</p><p><strong>Market access and licensing</strong>: If the purchaser uses the Software for commercial operation, it must lawfully obtain, in its place of registration and in every target jurisdiction of operation, all required financial licenses, virtual asset service provider (VASP) licenses, money services business (MSB) licenses or related administrative approvals.</p><p><strong>Anti-money laundering and customer verification</strong>: The purchaser has an independent obligation to establish sound anti-money laundering (AML), counter-terrorist financing (CFT) and know-your-customer (KYC/KYB) risk controls, meeting the Financial Action Task Force (FATF) &quot;Travel Rule&quot; and local laws and regulations.</p><p><strong>Data security and privacy</strong>: The purchaser must independently fulfil its compliance obligations under the laws and regulations of its country or region concerning personal data protection, cybersecurity and cross-border data flows (such as the GDPR).</p><h2 id="_3-strictly-prohibited-uses" tabindex="-1">3. Strictly prohibited uses <a class="header-anchor" href="#_3-strictly-prohibited-uses" aria-label="Permalink to &quot;3. Strictly prohibited uses&quot;">​</a></h2><p>The purchaser must not use the Software for any of the following:</p><p><strong>Illegal financial activities</strong>: Conducting, without approval, exchange between fiat and virtual currencies, exchange between virtual currencies, discretionary asset management for clients, unlawful token issuance for fundraising (ICO/IEO) or other illegal financial activities.</p><p><strong>Criminal activities</strong>: Money laundering, fraud, illegal fundraising, pyramid schemes, underground banking, gambling, darknet trading, evasion of foreign exchange controls, or providing services to individuals or regions subject to international sanctions (such as the OFAC entity lists).</p><p><strong>Prohibitions in strictly regulated jurisdictions</strong>: It is strictly prohibited to set up a trading platform for, or provide substantive business services to, local residents in jurisdictions that fully prohibit virtual currency trading and derivatives operations (including but not limited to mainland China).</p><h2 id="_4-as-is-delivery-and-security-audit-obligations" tabindex="-1">4. &quot;As-is&quot; delivery and security audit obligations <a class="header-anchor" href="#_4-as-is-delivery-and-security-audit-obligations" aria-label="Permalink to &quot;4. &quot;As-is&quot; delivery and security audit obligations&quot;">​</a></h2><p><strong>Provided as-is</strong>: Unless otherwise expressly agreed in writing by both parties, the Software is delivered &quot;as is&quot;. The delivering party makes no express or implied warranty that the system is entirely free of vulnerabilities or defects, has unlimited concurrency performance, or is immune to cyberattacks.</p><p><strong>Independent security audit obligation</strong>: For sensitive modules involving blockchain interaction, hot/cold wallet management, smart contracts and the matching engine, the purchaser must, before going live, engage a professional third-party security auditor for penetration testing, code audit and risk calibration. Asset losses caused by smart contract vulnerabilities, private key leaks or hacking are borne solely by the purchaser.</p><h2 id="_5-limitation-of-liability-and-right-of-recourse" tabindex="-1">5. Limitation of liability and right of recourse <a class="header-anchor" href="#_5-limitation-of-liability-and-right-of-recourse" aria-label="Permalink to &quot;5. Limitation of liability and right of recourse&quot;">​</a></h2><p><strong>Full exemption from liability</strong>: To the maximum extent permitted by law, the delivering party bears no liability for any direct, indirect, incidental or punitive loss (including but not limited to loss of funds, loss of profits, loss of goodwill, regulatory fines or criminal proceedings) suffered because the purchaser or its end users use, misuse or are unable to use the Software, or because the purchaser operates unlawfully or in breach of regulations.</p><p><strong>Recourse and indemnity</strong>: If the purchaser&#39;s breach of this Disclaimer, non-compliant operation or infringement of third-party rights causes the delivering party or its affiliates to face regulatory investigation, penalties, civil litigation or damage to goodwill, the purchaser shall fully indemnify the delivering party for all resulting losses (including reasonable legal fees, notarization fees, travel expenses and settlement amounts).</p><h2 id="_6-governing-law-and-dispute-resolution" tabindex="-1">6. Governing law and dispute resolution <a class="header-anchor" href="#_6-governing-law-and-dispute-resolution" aria-label="Permalink to &quot;6. Governing law and dispute resolution&quot;">​</a></h2><p>The validity, interpretation, performance and dispute resolution of this Disclaimer are governed by <strong>the laws of the Republic of Singapore</strong>. Any dispute arising from the Software shall first be resolved through friendly negotiation; failing that, it shall be submitted to the <strong>Singapore International Arbitration Centre (SIAC)</strong> for final and binding arbitration under its rules.</p><div class="tip custom-block"><p class="custom-block-title">Implementation note</p><p>Virtual asset regulation is highly territorial (for example, Dubai&#39;s VARA, Hong Kong&#39;s SFC and Singapore&#39;s MAS have very different look-through requirements for technology outsourcing and exchange licensing). Before signing externally, we recommend having this template reviewed by a practising lawyer experienced in cross-border financial compliance, and tailored to the specific delivery model (private deployment or SaaS) and target market.</p></div>',26)])])}const p=i(n,[["render",o]]);export{g as __pageData,p as default};
